package com.appnexus.platform.persistence.identity.oauth;
import com.appnexus.persistence.mybatis.PlatformScoped;
import org.apache.ibatis.annotations.*;
import java.util.List;
import java.util.Map;
/** OAuth标准表固定MyBatis存储，保留上游字段及序列化，不加入业务审计列。 */
@Mapper
@PlatformScoped(tables={"oauth2_registered_client","oauth2_authorization","oauth2_authorization_consent"})
public interface OAuthAuthorizationRepositoryMapper {
 /** 框架标准参数映射按固定列序写入，不改序列化或Token格式。 */
 @Insert("INSERT INTO oauth2_registered_client(id,client_id,client_id_issued_at,client_secret,client_secret_expires_at,client_name,client_authentication_methods,authorization_grant_types,redirect_uris,post_logout_redirect_uris,scopes,client_settings,token_settings) VALUES(#{values[0]},#{values[1]},#{values[2]},#{values[3]},#{values[4]},#{values[5]},#{values[6]},#{values[7]},#{values[8]},#{values[9]},#{values[10]},#{values[11]},#{values[12]}) ON DUPLICATE KEY UPDATE client_id=VALUES(client_id),client_id_issued_at=VALUES(client_id_issued_at),client_secret=VALUES(client_secret),client_secret_expires_at=VALUES(client_secret_expires_at),client_name=VALUES(client_name),client_authentication_methods=VALUES(client_authentication_methods),authorization_grant_types=VALUES(authorization_grant_types),redirect_uris=VALUES(redirect_uris),post_logout_redirect_uris=VALUES(post_logout_redirect_uris),scopes=VALUES(scopes),client_settings=VALUES(client_settings),token_settings=VALUES(token_settings)") int saveClient(@Param("values") List<Object> values);
 /** 框架标准参数映射按固定列序写入，不改序列化或Token格式。 */
 @Insert("INSERT INTO oauth2_authorization(id,registered_client_id,principal_name,authorization_grant_type,authorized_scopes,attributes,state,authorization_code_value,authorization_code_issued_at,authorization_code_expires_at,authorization_code_metadata,access_token_value,access_token_issued_at,access_token_expires_at,access_token_metadata,access_token_type,access_token_scopes,oidc_id_token_value,oidc_id_token_issued_at,oidc_id_token_expires_at,oidc_id_token_metadata,refresh_token_value,refresh_token_issued_at,refresh_token_expires_at,refresh_token_metadata,user_code_value,user_code_issued_at,user_code_expires_at,user_code_metadata,device_code_value,device_code_issued_at,device_code_expires_at,device_code_metadata) VALUES(#{values[0]},#{values[1]},#{values[2]},#{values[3]},#{values[4]},#{values[5]},#{values[6]},#{values[7]},#{values[8]},#{values[9]},#{values[10]},#{values[11]},#{values[12]},#{values[13]},#{values[14]},#{values[15]},#{values[16]},#{values[17]},#{values[18]},#{values[19]},#{values[20]},#{values[21]},#{values[22]},#{values[23]},#{values[24]},#{values[25]},#{values[26]},#{values[27]},#{values[28]},#{values[29]},#{values[30]},#{values[31]},#{values[32]}) ON DUPLICATE KEY UPDATE authorization_grant_type=VALUES(authorization_grant_type),authorized_scopes=VALUES(authorized_scopes),attributes=VALUES(attributes),state=VALUES(state),authorization_code_value=VALUES(authorization_code_value),authorization_code_issued_at=VALUES(authorization_code_issued_at),authorization_code_expires_at=VALUES(authorization_code_expires_at),authorization_code_metadata=VALUES(authorization_code_metadata),access_token_value=VALUES(access_token_value),access_token_issued_at=VALUES(access_token_issued_at),access_token_expires_at=VALUES(access_token_expires_at),access_token_metadata=VALUES(access_token_metadata),access_token_type=VALUES(access_token_type),access_token_scopes=VALUES(access_token_scopes),oidc_id_token_value=VALUES(oidc_id_token_value),oidc_id_token_issued_at=VALUES(oidc_id_token_issued_at),oidc_id_token_expires_at=VALUES(oidc_id_token_expires_at),oidc_id_token_metadata=VALUES(oidc_id_token_metadata),refresh_token_value=VALUES(refresh_token_value),refresh_token_issued_at=VALUES(refresh_token_issued_at),refresh_token_expires_at=VALUES(refresh_token_expires_at),refresh_token_metadata=VALUES(refresh_token_metadata),user_code_value=VALUES(user_code_value),user_code_issued_at=VALUES(user_code_issued_at),user_code_expires_at=VALUES(user_code_expires_at),user_code_metadata=VALUES(user_code_metadata),device_code_value=VALUES(device_code_value),device_code_issued_at=VALUES(device_code_issued_at),device_code_expires_at=VALUES(device_code_expires_at),device_code_metadata=VALUES(device_code_metadata)") int saveAuthorization(@Param("values") List<Object> values);
 /** 框架标准参数映射按固定列序写入，不改序列化或Token格式。 */
 @Insert("INSERT INTO oauth2_authorization_consent(registered_client_id,principal_name,authorities) VALUES(#{values[0]},#{values[1]},#{values[2]}) ON DUPLICATE KEY UPDATE authorities=VALUES(authorities)") int saveConsent(@Param("values") List<Object> values);
 @Select("SELECT * FROM oauth2_registered_client WHERE id=#{id}") Map<String,Object> clientById(@Param("id") String id);
 @Select("SELECT * FROM oauth2_registered_client WHERE client_id=#{id}") Map<String,Object> clientByClientId(@Param("id") String id);
 @Select("SELECT * FROM oauth2_authorization WHERE id=#{id}") Map<String,Object> authorizationById(@Param("id") String id);
 @Delete("DELETE FROM oauth2_authorization WHERE id=#{id}") int removeAuthorization(@Param("id") String id);
 @Select("SELECT * FROM oauth2_authorization_consent WHERE registered_client_id=#{client} AND principal_name=#{principal}") Map<String,Object> consent(@Param("client") String client,@Param("principal") String principal);
 @Delete("DELETE FROM oauth2_authorization_consent WHERE registered_client_id=#{client} AND principal_name=#{principal}") int removeConsent(@Param("client") String client,@Param("principal") String principal);
 @SelectProvider(type=TokenSql.class,method="query") List<Map<String,Object>> byToken(@Param("value") String value,@Param("kind") String kind);
 final class TokenSql {
  private TokenSql(){}
  /** @param parameters 框架Token类型及凭据，不允许任意列名 @return 固定Token列查询，凭据始终绑定且不记录日志 */
  public static String query(Map<String,Object> parameters){var columns=Map.of("state","state","code","authorization_code_value","access_token","access_token_value","id_token","oidc_id_token_value","refresh_token","refresh_token_value","user_code","user_code_value","device_code","device_code_value");String kind=(String)parameters.get("kind");if(kind!=null&&!columns.containsKey(kind))return "SELECT * FROM oauth2_authorization WHERE 1=0";var matches=new java.util.ArrayList<String>();for(var entry:columns.entrySet())if(kind==null||kind.equals(entry.getKey()))matches.add(entry.getValue()+"=#{value}");return "SELECT * FROM oauth2_authorization WHERE "+String.join(" OR ",matches);}
 }
}
